// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address owner;

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new PoCGame(address(this), 0);
        vm.stopPrank();
        owner = __invmut_eoa;
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount < type(uint256).max);
        vm.prank(owner);
        c.AdjustDifficulty(amount);
        assertTrue(c.currentDifficulty() == amount);
    }
}
